#pragma once#include <HcdMemoryService.h>#include "IHcdController.h"#include <HcdVarInfo.h>#ifdef HCDFACTORY_EXPORTS#define HCDFACTORY_API Q_DECL_DLLEXPORT     #else#define HCDFACTORY_API Q_DECL_DLLIMPORT     #endifstruct HCDFACTORY_API SStepCalcParams{  tAnalog32 dtS;  DWORD nStep;  __time64_t modelTime;  LPCSTR pszObjName;  SStepCalcParams() : dtS(0), nStep(0), modelTime(0), pszObjName( NULL )  {}};struct SParamInfo : SVarInfo{  BYTE *Addr;  bool bParameter;  SParamInfo() : Addr( NULL ), bParameter(false){}};struct SProjRestedParams{  enum  {    N = 4,    L = 8,  };  SProjRestedParams()  {    ZeroMemory( this, sizeof(*this) );  }  IHcdController *pCtrl;  char szAddrs[N][L];  char szNumbs[N][L];  int nPositions[N];  char szIP[32];  DWORD dwIP;  int domain;};struct HCDFACTORY_API IHcdElement{  int ID, ExecOrder;  char szName[32];  LPCSTR m_pszType;  NEWHCD;  virtual BYTE* GetField( LPCSTR pszName, eHcdVType *pType = NULL, tHcdVarSizeType_ *pVarSize = NULL, LPCSTR *ppszEnum = NULL ) = 0;  virtual void OnCreated( int domain, LPCSTR pszHmiTagName ) = 0;  virtual void OnFilledProjectSettings() = 0;  virtual int SetProjectValue( LPCSTR pszName, LPCSTR pszValue ) = 0;  virtual void ProjectRestored( SProjRestedParams &params, int N ) = 0;  virtual void StepCalc( SStepCalcParams &params ) = 0;  virtual size_t EnumFields( SParamInfo *pVars, size_t nCount ) = 0;  virtual void CreateModbusFields( SProjRestedParams &params, LPCSTR pszField ) = 0;};